      new Error('Unique constraint failed'),
    );
    await expect(created.service.runOnce(NOW)).resolves.toBe(true);
    expect(created.analyzer.analyze).not.toHaveBeenCalled();

    const updated = setup([
      [candidate({ analysisUpdatedAt: ROW_UPDATED_AT, attempts: 1 })],
